 summary=agg.groupby('year').agg(observed_complexes=('complex_id','size'),under=('status',lambda x:int(x.eq('under').sum())),over=('status',lambda x:int(x.eq('over').sum())),n_valid=('n','sum'),single_trade_complexes=('n',lambda x:int(x.eq(1).sum()))).reset_index();summary=summary.merge(pd.DataFrame(summary_states),on='year',validate='one_to_one');assert (summary.observed_complexes+summary.no_trade+summary.not_yet_observed==summary.catalog_count).all();summary['period']=np.where(summary.year.eq(2026),'partial_year','calendar_year');summary.to_csv(OUT/'annual_summary_complete.csv',index=False,encoding='utf-8-sig')
