 s={'complete_region_months':len(receipts),'fresh_all_area_rows':rawtotal,'old_staged_84_rows_replaced':old_count,'old_raw_staged_84_mismatch_pairs':sum(not x['old_raw_staged_84_match'] for x in pair_accounting),'fresh_84_rows':len(f),'kept_staged_84_rows':len(kept),'total_84_source_rows':len(allrows),'valid_84_price_rows':len(v),'cancelled_rows':int(canceled.sum()),'bad_price_rows':int(bad_price.sum()),'invalid_id_rows':int(invalid_id.sum()),'bad_date_rows':int(bad_date.sum()),'canonical_complexes':v.complex_id.nunique(),'annual_n_sum':int(agg.n.sum()),'legacy_same_date_floor_area_distinct_price_groups':collision_groups,'legacy_collapse_would_remove_rows':legacy_would_drop,'multi_sigungu_same_complex_year_groups':len(cross),'item_multiplicity_preserved':True,'global_master_or_raw_modified':False,'latest_contract_date':str(v.deal_date.max().date()),'collection_fresh_complete_for_266_only':True,'remaining_source_condition':'untouched cached region-months have raw row counts >= reported total, but historical changes/account identity coverage are not universally refreshed'};assert len(allrows)==len(kept)+len(f);assert int(agg.n.sum())==len(v);(OUT/'row_accounting.json').write_text(json.dumps(s,ensure_ascii=False,indent=2),encoding='utf8');print(json.dumps(s,ensure_ascii=False),flush=True)
